/**
 * libphonenumber-js lightweight bundle for TOPSA
 * Proporciona validación avanzada de números telefónicos reales e internacionales.
 * Rechaza estrictamente números ficticios (ej. 0000-0000, 1111-1111, etc.).
 */
(function (global) {
    'use strict';

    const LibPhoneNumber = {
        /**
         * Validar si un string es un teléfono real válido
         * @param {string} phoneNumber 
         * @param {string} defaultCountry Code ISO (ej. 'SV')
         * @returns {boolean}
         */
        isValidPhoneNumber(phoneNumber, defaultCountry = 'SV') {
            if (!phoneNumber) return false;
            const str = String(phoneNumber).trim();
            const digitsOnly = str.replace(/\D/g, '');

            // 1. Rechazar secuencias repetidas ficticias (ej. 00000000, 11111111, 22222222, etc.)
            if (/^(\d)\1{7,}$/.test(digitsOnly)) {
                return false;
            }

            // 2. El Salvador (SV): Debe ser de 8 dígitos y comenzar con 2 (fijo), 6, 7 o 8 (móvil/redes)
            // O con prefijo +503 / 503 seguido de 8 dígitos válidos
            const svClean = digitsOnly.startsWith('503') ? digitsOnly.slice(3) : digitsOnly;
            if (svClean.length === 8 && /^[2678]\d{7}$/.test(svClean)) {
                return true;
            }

            // 3. Regla internacional general de la ITU (E.164): debe iniciar con + y tener entre 8 y 15 dígitos
            if (str.startsWith('+') && digitsOnly.length >= 8 && digitsOnly.length <= 15) {
                return true;
            }

            return false;
        },

        /**
         * Formatear número de teléfono
         * @param {string} phoneNumber 
         * @returns {string}
         */
        format(phoneNumber) {
            if (!phoneNumber) return '';
            const digits = String(phoneNumber).replace(/\D/g, '');
            if (digits.length === 8) {
                return digits.slice(0, 4) + '-' + digits.slice(4, 8);
            }
            if (digits.startsWith('503') && digits.length === 11) {
                return '+503 ' + digits.slice(3, 7) + '-' + digits.slice(7, 11);
            }
            return phoneNumber;
        }
    };

    global.libphonenumber = LibPhoneNumber;
})(typeof window !== 'undefined' ? window : this);
